script:
(function() {
  // Poppins — document-level so it reaches this block's shadow root.
  try {
    if (!document.querySelector('link[data-pr-poppins]')) {
      var pf = document.createElement('link'); pf.rel = 'stylesheet'; pf.setAttribute('data-pr-poppins', '1');
      pf.href = 'https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap';
      document.head.appendChild(pf);
    }
  } catch (e) {}

  var host  = root_element.querySelector('[data-prn-crops]');
  var empty = root_element.querySelector('[data-prn-empty]');
  if (!host) return;

  var esc = (window.frappe && frappe.utils && frappe.utils.escape_html)
    ? frappe.utils.escape_html
    : function(s) { return (s || '').replace(/[&<>"']/g, function(c) {
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };

  // The app's pages, in its sidebar order. Inner SVG only (lucide); the
  // wrapper is written once below so every tile draws the same way.
  var VIEWS = [
    ['overview', 'Overview', 'KPIs for the week', '<rect x="3" y="3" width="7" height="9"/><rect x="14" y="3" width="7" height="5"/><rect x="14" y="12" width="7" height="9"/><rect x="3" y="16" width="7" height="5"/>'],
    ['plan', 'Weekly Plan', 'Tasks and tick-off', '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/><path d="m9 16 2 2 4-4"/>'],
    ['blocks', 'Blocks', 'Units and areas', '<path d="M14.1 6 9.9 4 3 7v13l6.9-3 4.2 2L21 16V3z"/><path d="M9.9 4v13M14.1 6v13"/>'],
    ['cycles', 'Crop Cycles', 'Planting to harvest', '<path d="M7 20h10"/><path d="M10 20c5.5-2.5.8-6.4 3-10"/><path d="M9.5 9.4c1.1.8 1.8 2.2 2.3 3.7-2 .4-3.5.4-4.8-.3-1.2-.6-2.3-1.9-3-4.2 2.8-.5 4.4 0 5.5.8z"/><path d="M14.1 6a7 7 0 0 0-1.1 4c1.9-.1 3.3-.6 4.3-1.4 1-1 1.6-2.3 1.7-4.6-2.7.1-4 1-4.9 2z"/>'],
    ['value-adders', 'Value Adders', 'Work done and pay', '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>'],
    ['costs', 'Block Costs', 'Labour, inputs, value', '<path d="M19 7V4a1 1 0 0 0-1-1H5a2 2 0 0 0 0 4h15a1 1 0 0 1 1 1v4h-3a2 2 0 0 0 0 4h3a1 1 0 0 0 1-1v-2a1 1 0 0 0-1-1"/><path d="M3 5v14a2 2 0 0 0 2 2h15a1 1 0 0 0 1-1v-4"/>'],
    ['forecast', 'Forecast', 'Forecast vs actual', '<path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-3 3"/>'],
    ['settings', 'Settings', 'Rates and protocols', '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>']
  ];

  // Added to every crop's tiles.
  var APPROVALS = ['approvals', 'Approvals', 'Review supervisors\' work', '<path d="M9 12l2 2 4-4"/><path d="M21 12c0 4.97-4.03 9-9 9s-9-4.03-9-9 4.03-9 9-9 9 4.03 9 9z"/>'];
  var MAP = ['map', 'Coverage Map', 'Plan progress by block', '<path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0z"/><circle cx="12" cy="10" r="3"/>'];
  // Extra views only some crops have, keyed by Production Crop.crop_key.
  var EXTRA = {
    'avocado': [
      ['outlook', 'Season Outlook', 'Forecast for the season', '<path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-3 3"/>'],
      ['block-forecast', 'Block Forecast', 'Yield by block', '<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/>'],
      ['harvest-calendar', 'Harvest Calendar', 'When blocks are ready', '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>'],
      ['picking-plan', 'Picking Plan', 'Labour for the harvest', '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/>'],
      ['dry-matter', 'Dry Matter', 'Fruit maturity', '<path d="M12 2.7l5.7 5.7a8 8 0 1 1-11.4 0z"/>']
    ],
    'apiary': [
      ['hive-inspections', 'Hive Inspections', 'Colony health checks', '<path d="M11 2a2 2 0 0 0-2 2v5H4a2 2 0 0 0-2 2v2c0 1.1.9 2 2 2h5v5c0 1.1.9 2 2 2h2c1.1 0 2-.9 2-2v-5h5a2 2 0 0 0 2-2v-2a2 2 0 0 0-2-2h-5V4a2 2 0 0 0-2-2z"/>'],
      ['honey-harvest', 'Honey Harvest', 'Supers and yield', '<path d="M12 2l8 4.5v9L12 20l-8-4.5v-9z"/>']
    ],
    'aquaculture': [
      ['pond-batches', 'Pond Batches', 'Stocking and growth', '<path d="M6.5 12c.94-3.46 4.94-6 8.5-6 3.56 0 6.06 2.54 7 6-.94 3.47-3.44 6-7 6s-7.56-2.53-8.5-6z"/><path d="M18 12v.5"/><path d="M16 17.93a9.77 9.77 0 0 1 0-11.86"/>'],
      ['water-quality', 'Water Quality', 'Readings by pond', '<path d="M12 2.7l5.7 5.7a8 8 0 1 1-11.4 0z"/>'],
      ['feeding', 'Feeding & Mortality', 'Feed given and losses', '<path d="M3 2v7c0 1.1.9 2 2 2h4a2 2 0 0 0 2-2V2"/><path d="M7 2v20"/><path d="M21 15V2a5 5 0 0 0-5 5v6c0 1.1.9 2 2 2h3zm0 0v7"/>']
    ],
    'fruits-vegetables': [
      ['irrigation', 'Pivot Irrigation', 'Runs and water use', '<path d="M12 2.7l5.7 5.7a8 8 0 1 1-11.4 0z"/>'],
      ['grading', 'Harvest Grading', 'Grades and rejects', '<path d="M12 3l2.9 5.9 6.5.9-4.7 4.6 1.1 6.5L12 17.8 6.2 20.9l1.1-6.5L2.6 9.8l6.5-.9z"/>']
    ]
  };

  // Bees and fish run in hives and ponds, not crop cycles. Uses the Production Crop
  // flag from the bootstrap, falling back to the crop key.
  function usesCycles(crop) {
    if (crop.uses_crop_cycles !== undefined && crop.uses_crop_cycles !== null) return !!Number(crop.uses_crop_cycles);
    return ['apiary', 'aquaculture'].indexOf(crop.crop_key) < 0;
  }

  function section(crop) {
    var colour = /^#[0-9a-f]{6}$/i.test(crop.accent_color || '') ? crop.accent_color : '#3f7d3a';
    var cycles = usesCycles(crop);
    var base = VIEWS.filter(function(v) { return cycles || v[0] !== 'cycles'; });
    // The generic Blocks tile uses the crop's own word for its unit (Ponds, Hive Groups).
    base = base.map(function(v) {
      return v[0] === 'blocks' && crop.unit_label ? ['blocks', crop.unit_label + 's', 'Units and areas', v[3]] : v;
    });
    var views = base.slice(0, 1).concat([APPROVALS]).concat(base.slice(1)).concat([MAP]).concat(EXTRA[crop.crop_key] || []);
    var tiles = views.map(function(v) {
      var href = '/production_app#/' + encodeURIComponent(crop.crop_key) + '/' + v[0];
      return '<a class="prn-tile" href="' + esc(href) + '">'
        + '<span class="prn-ic" style="background:' + colour + '1a;color:' + colour + '">'
        + '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
        + v[3] + '</svg></span>'
        + '<span class="prn-tx"><span class="prn-lb">' + esc(v[1]) + '</span>'
        + '<span class="prn-sub">' + esc(v[2]) + '</span></span></a>';
    }).join('');
    return '<section class="prn-crop">'
      + '<div class="prn-crophead"><span class="prn-dot" style="background:' + colour + '"></span>'
      + '<span class="prn-cropname">' + esc(crop.name) + '</span></div>'
      + '<div class="prn-grid">' + tiles + '</div>'
      + '</section>';
  }

  function render(crops) {
    if (!crops || !crops.length) {
      if (empty) empty.hidden = false;
      return;
    }
    if (empty) empty.hidden = true;
    host.innerHTML = crops.map(section).join('');
  }

  // "Awaiting approval" strip: pending submissions per crop, stale ones in red.
  var awaitBox = root_element.querySelector('[data-prn-await]');
  var awaitRow = root_element.querySelector('[data-prn-await-row]');
  function renderAwait(res) {
    if (!awaitBox || !awaitRow || !res || !res.crops || !res.crops.length) return;
    awaitRow.innerHTML = res.crops.map(function(c) {
      var href = '/production_app#/' + encodeURIComponent(c.crop_key || '') + '/approvals';
      var protos = Number(c.protocols_pending) || 0;
      return '<a class="prn-chip" href="' + esc(href) + '"><span class="prn-chip-n">' + (c.pending || 0) + '</span>'
        + '<span class="prn-chip-l">' + esc(c.crop) + '</span>'
        + (protos ? '<span class="prn-proto">' + protos + (protos === 1 ? ' protocol' : ' protocols') + '</span>' : '')
        + (c.stale ? '<span class="prn-stale">' + c.stale + ' stale</span>' : '') + '</a>';
    }).join('');
    awaitBox.hidden = false;
  }

  if (window.frappe && frappe.call) {
    frappe.call({
      method: 'upande_production.api.production.get_bootstrap',
      callback: function(r) { render(r && r.message && r.message.crops); },
      error: function() { if (empty) empty.hidden = false; }
    });
    frappe.call({
      method: 'upande_production.api.approvals.approval_counts',
      callback: function(r) { var m = r && r.message; if (m && !m.error) renderAwait(m); }
    });
  } else if (empty) {
    empty.hidden = false;
  }
})();

style:
.prn{padding:4px 2px;font-family:'Poppins',var(--font-stack),'Inter',sans-serif;}
.prn-title{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#8a8f98;font-weight:600;margin:0 0 12px 2px;}
.prn-crop{padding:0 0 18px;}
.prn-crop:last-child{padding-bottom:4px;}
.prn-crophead{display:flex;align-items:center;gap:9px;margin:0 0 9px 2px;}
.prn-dot{width:10px;height:10px;border-radius:50%;flex:0 0 auto;}
.prn-cropname{font-size:14px;font-weight:600;letter-spacing:-.01em;}
.prn-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px;}
.prn-tile{display:flex;align-items:center;gap:11px;padding:13px 15px;border:1px solid var(--border-color,#e2e4e9);border-radius:10px;background:var(--card-bg,#fff);text-decoration:none;color:inherit;transition:box-shadow .18s ease,transform .18s ease;}
.prn-tile:hover{box-shadow:0 2px 6px rgba(0,0,0,.06);transform:translateY(-1px);text-decoration:none;}
.prn-ic{width:36px;height:36px;border-radius:9px;display:flex;align-items:center;justify-content:center;flex:0 0 auto;}
.prn-ic svg{width:18px;height:18px;}
.prn-tx{display:flex;flex-direction:column;min-width:0;}
.prn-lb{font-size:13px;font-weight:600;letter-spacing:-.01em;}
.prn-sub{font-size:11px;color:#8a8f98;margin-top:1px;}
.prn-empty{font-size:12px;color:#8a8f98;padding:8px 2px;}
.prn-await{margin:0 0 20px;}
.prn-await-title{margin-bottom:8px;}
.prn-await-row{display:flex;flex-wrap:wrap;gap:8px;}
.prn-chip{display:inline-flex;align-items:center;gap:8px;padding:7px 13px;border:1px solid var(--border-color,#e2e4e9);border-radius:999px;background:var(--card-bg,#fff);text-decoration:none;color:inherit;font-size:12px;transition:box-shadow .18s ease;}
.prn-chip:hover{box-shadow:0 2px 6px rgba(0,0,0,.06);text-decoration:none;}
.prn-chip-n{font-weight:700;font-size:14px;font-variant-numeric:tabular-nums;}
.prn-chip-l{color:#5b6068;font-weight:500;}
.prn-stale{color:#d6342b;font-weight:600;font-size:11px;background:#d6342b14;border-radius:999px;padding:1px 8px;}
.prn-proto{color:#8a5a00;font-weight:600;font-size:11px;background:#e8a31a1f;border-radius:999px;padding:1px 8px;}
